#!/bin/sh
# bench.sh - bench-standard 0.5.0, everything in one file: run ./bench.sh --help
# Generated by dev/build.sh from dev/ - edit there and rebuild, not here.
set -eu
BENCH_HOME=${BENCH_HOME:-$(cd "$(dirname "$0")" && pwd)}; export BENCH_HOME
d=$(mktemp -d)
trap 'rm -rf "$d"' EXIT
trap 'rm -rf "$d"; exit 130' INT
trap 'rm -rf "$d"; exit 143' TERM
cat > "$d/bench.sh" <<'__BENCH_STANDARD_EOF__'
#!/bin/sh
# bench.sh - bench-standard: benchmark an LLM server the way everyone in the
# group does, with BetterBench 0.6.1+. Every result records its setup (GPU,
# PCIe, engine, launch flags, ...), so results stay comparable.
#
# A quick check (a few minutes), then the same with --full for the real run:
#   ./bench.sh --endpoint http://localhost:8080/v1 --model MODEL_ID \
#     --tp 1 --pp 1 --quant Q4_K_M --kv f16 --spec none --thinking default \
#     --submitter YOUR_NAME --server-cmd-file server-cmd.txt
#
# You declare (these can't be detected):
#   --tp N / --pp N      tensor / pipeline parallel size
#   --quant Q            weight quantization: Q4_K_M, UD-Q4_K_M, w4a16, bf16
#   --kv KV              KV cache type: f16, bf16, q8_0
#   --spec S             speculative decoding: none, or METHOD:N with METHOD
#                        mtp, eagle, eagle3, ngram or draft (e.g. mtp:5)
#   --thinking T         thinking mode set on the server: off, on, low, medium,
#                        high or default
#   --submitter NAME     you
#   --server-cmd-file F  the command that started the server (not needed
#                        behind llama-swap, which reports it)
#
# Options:
#   --full               the run that counts (default: a quick check)
#   --verbose            show all of BetterBench's output
#   --dry-run            detect everything, print what would run, stop
#   --mem-bw GBPS        the card's spec memory bandwidth (measured anyway)
#   --power-limit W      when it can't be read from the GPU, or 'stock'
#   --pcie "Gen4 x16"    inside a VM, where the link can't be read
#   --special-notes TXT  anything unusual: custom kernels, undervolt, ...
#   --api-key KEY        or $BETTERBENCH_API_KEY; never stored
#   --no-concurrency     skip the concurrency sweep
#   --results-dir DIR    default: results/ next to bench.sh
#   --env-file FILE      when BetterBench runs on another machine than the GPU:
#                        the output of 'bench.sh collect-env' run on the GPU box
#
# Other commands:
#   bench.sh collect-env --endpoint URL --model ID   print the detected setup
#   bench.sh power [SECONDS]   sample GPU power, energy and clock until killed
#   bench.sh --version
#
# Values can also come from the environment: BENCH_TP, BENCH_PP, BENCH_QUANT,
# BENCH_KV, BENCH_SPEC, BENCH_THINKING, BENCH_SUBMITTER, BENCH_POWER_LIMIT,
# BENCH_PCIE, BENCH_MEM_BW, BENCH_SPECIAL_NOTES, BENCH_RESULTS_DIR. Machine-
# local defaults like these go in bench.local.env next to bench.sh.
# Send the whole results/<run>/ folder. Only --full runs count.
# The standard models and their hashes: README.md. For agents: AGENTS.md.

set -eu
umask 002
# here: the helper files. home: where results and bench.local.env go - next to
# the bench.sh people run, which unpacks the helpers to a temp dir.
here=$(cd "$(dirname "$0")" && pwd)
home=${BENCH_HOME:-$here}
. "$here/standard.env"
# Machine-local defaults (e.g. BENCH_RESULTS_DIR), not part of the standard.
[ -f "$home/bench.local.env" ] && . "$home/bench.local.env"

die() { echo "bench.sh: $*" >&2; exit 1; }
usage() { sed -n '2,/^$/p' "$0" | sed -e 's/^# \{0,1\}//' -e '$d'; exit "${1:-0}"; }

case "${1:-}" in
  collect-env) shift; exec sh "$here/collect-env.sh" "$@" ;;
  power)       shift; exec sh "$here/gpu-power.sh" "$@" ;;
  --version)   echo "bench-standard $STANDARD_VERSION (BetterBench $BETTERBENCH_MIN_VERSION or newer)"; exit 0 ;;
esac

endpoint="" model="" server_cmd_file="" env_file="" quick=1 no_conc=0 dry=0 verbose=0
tp=${BENCH_TP:-} pp=${BENCH_PP:-} quant=${BENCH_QUANT:-} kv=${BENCH_KV:-}
spec=${BENCH_SPEC:-} thinking=${BENCH_THINKING:-} power_limit=${BENCH_POWER_LIMIT:-}
submitter=${BENCH_SUBMITTER:-} pcie=${BENCH_PCIE:-} special=${BENCH_SPECIAL_NOTES:-}
mem_bw=${BENCH_MEM_BW:-}
results_dir=${BENCH_RESULTS_DIR:-$home/results}

need() { [ "$1" -ge 2 ] || die "$2 needs a value"; }
while [ $# -gt 0 ]; do
  case "$1" in
    --endpoint)        need $# "$1"; endpoint=$2; shift 2 ;;
    --model)           need $# "$1"; model=$2; shift 2 ;;
    --api-key)         need $# "$1"; BETTERBENCH_API_KEY=$2; export BETTERBENCH_API_KEY; shift 2 ;;
    --server-cmd-file) need $# "$1"; server_cmd_file=$2; shift 2 ;;
    --env-file)        need $# "$1"; env_file=$2; shift 2 ;;
    --results-dir)     need $# "$1"; results_dir=$2; shift 2 ;;
    --tp)              need $# "$1"; tp=$2; shift 2 ;;
    --pp)              need $# "$1"; pp=$2; shift 2 ;;
    --quant)           need $# "$1"; quant=$2; shift 2 ;;
    --kv)              need $# "$1"; kv=$2; shift 2 ;;
    --spec)            need $# "$1"; spec=$2; shift 2 ;;
    --thinking)        need $# "$1"; thinking=$2; shift 2 ;;
    --power-limit)     need $# "$1"; power_limit=$2; shift 2 ;;
    --submitter)       need $# "$1"; submitter=$2; shift 2 ;;
    --pcie)            need $# "$1"; pcie=$2; shift 2 ;;
    --special-notes)   need $# "$1"; special=$2; shift 2 ;;
    --mem-bw)          need $# "$1"; mem_bw=$2; shift 2 ;;
    --quick)           quick=1; shift ;;
    --full)            quick=0; shift ;;
    --no-concurrency)  no_conc=1; shift ;;
    --dry-run)         dry=1; shift ;;
    --verbose)         verbose=1; shift ;;
    -h|--help)         usage 0 ;;
    *) echo "bench.sh: unknown argument: $1 (other BetterBench flags are not allowed)" >&2; usage 2 ;;
  esac
done

# ---------------------------------------------------------------- checks
matches() { printf '%s\n' "$1" | grep -Eqx "$2"; }

command -v python3 >/dev/null || die "python3 not found"
have_ver=$(betterbench --version 2>/dev/null | awk '{print $NF}') || have_ver=""
python3 -c 'import re, sys
v = lambda s: tuple(int(x) for x in re.findall(r"\d+", s)[:3])
sys.exit(not sys.argv[1] or v(sys.argv[1]) < v(sys.argv[2]))' "$have_ver" "$BETTERBENCH_MIN_VERSION" ||
  die "BetterBench $BETTERBENCH_MIN_VERSION or newer required, found '${have_ver:-not installed}'" \
      "(see https://github.com/GGZ14/BetterBench)"
command -v curl >/dev/null || die "curl not found"
# The exact build: two installs can both say 0.6.1. pip records where it came
# from: a git commit, or a local checkout (then git describes it).
bb_build=$(bb=$(command -v betterbench) && py=$(sed -n '1s/^#!//p' "$(readlink -f "$bb")") &&
  $py -c 'import importlib.metadata as m, json
u = json.loads(m.distribution("betterbench").read_text("direct_url.json") or "{}")
c = (u.get("vcs_info") or {}).get("commit_id")
print(c[:12] if c else u.get("url", "")[7:] if u.get("url", "").startswith("file://") else "")' 2>/dev/null) || bb_build=""
if [ -d "$bb_build" ]; then
  bb_build=$(git -c safe.directory='*' -C "$bb_build" describe --tags --always --dirty 2>/dev/null) || bb_build=""
fi

missing=""
for f in endpoint model tp pp quant kv spec thinking submitter; do
  eval "v=\${$f}"
  [ -n "$v" ] || missing="$missing --$(printf '%s' "$f" | tr _ -)"
done
[ -z "$missing" ] || die "missing mandatory value(s):$missing"

matches "$tp" '[1-9][0-9]*'               || die "--tp must be a positive integer"
matches "$pp" '[1-9][0-9]*'               || die "--pp must be a positive integer"
matches "$spec" 'none|(mtp|eagle|eagle3|ngram|draft):[1-9][0-9]*' ||
  die "--spec must be none or METHOD:N (mtp|eagle|eagle3|ngram|draft), e.g. mtp:5"
matches "$thinking" 'off|on|low|medium|high|default' ||
  die "--thinking must be off|on|low|medium|high|default (the server-side mode)"
[ -z "$power_limit" ] || matches "$power_limit" 'stock|[0-9]+(\.[0-9]+)?' ||
  die "--power-limit must be watts or 'stock'"
[ -z "$pcie" ] || matches "$pcie" 'Gen[1-6] x(1|2|4|8|16|32)' || die "--pcie must look like 'Gen4 x16'"
[ -z "$mem_bw" ] || matches "$mem_bw" '[1-9][0-9]*(\.[0-9]+)?' || die "--mem-bw must be GB/s, e.g. 456"
case "$special" in *"
"*) die "--special-notes must be a single line" ;; esac
for f in quant kv submitter; do
  eval "v=\${$f}"
  matches "$v" '[^[:space:]=]+' || die "--$f must be one word without '='"
done
if [ -n "$server_cmd_file" ]; then [ -r "$server_cmd_file" ] || die "cannot read $server_cmd_file"; fi
if [ -n "$env_file" ]; then [ -r "$env_file" ] || die "cannot read $env_file"; fi

tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT INT TERM

hdr="$tmp/hdr"
if [ -n "${BETTERBENCH_API_KEY:-}" ]; then printf 'Authorization: Bearer %s\n' "$BETTERBENCH_API_KEY" > "$hdr"
else printf 'Accept: application/json\n' > "$hdr"; fi

# ---------------------------------------------------------------- warm up
# The first request through llama-swap loads the model (minutes); it must not
# land inside a timed pass, and the engine probe needs it loaded anyway.
echo "warming up $model (a cold model behind llama-swap takes minutes to load) ..." >&2
body=$(python3 -c 'import json, sys; print(json.dumps({"model": sys.argv[1], "max_tokens": 1,
  "messages": [{"role": "user", "content": "hi"}]}))' "$model")
code=$(curl -s -m "${WARM_TIMEOUT:-900}" -o "$tmp/warm" -w '%{http_code}' -H @"$hdr" \
       -H 'Content-Type: application/json' -d "$body" "${endpoint%/}/chat/completions") || code=000
case "$code" in 2*) ;; *) die "warm-up request failed (HTTP $code): $(head -c 300 "$tmp/warm" 2>/dev/null)" ;; esac

# ---------------------------------------------------------------- greedy check
# The same prompt three times at temperature 0 must give the same text. The
# hash of that text also lets two setups of the same model be compared: a
# different hash means different numerics (quant, kernels, spec decoding bug).
# Whether the replies hold reasoning is checked against --thinking below.
echo "greedy check: 3 requests at temperature 0 ..." >&2
ENDPOINT=$endpoint MODEL=$model python3 - > "$tmp/measured" <<'PY'
import hashlib, json, os, urllib.request
PROMPT = ("List the first twelve prime numbers, then explain in three sentences "
          "why there are infinitely many primes.")
body = json.dumps({"model": os.environ["MODEL"], "temperature": 0, "seed": 0,
                   "max_tokens": 128, "stream": False,
                   "messages": [{"role": "user", "content": PROMPT}]}).encode()
hdr = {"Content-Type": "application/json"}
if os.environ.get("BETTERBENCH_API_KEY"):
    hdr["Authorization"] = "Bearer " + os.environ["BETTERBENCH_API_KEY"]
outs, thought = [], []
try:
    for _ in range(3):
        req = urllib.request.Request(os.environ["ENDPOINT"].rstrip("/") + "/chat/completions",
                                     body, hdr)
        with urllib.request.urlopen(req, timeout=600) as r:
            msg = json.load(r)["choices"][0]["message"]
        # thinking models may spend all 128 tokens on reasoning
        reasoning = msg.get("reasoning_content") or msg.get("reasoning") or ""
        content = msg.get("content") or ""
        outs.append(reasoning + "\0" + content)
        # a separate reasoning field (server with a reasoning parser), or
        # think tags left in the text (server without one)
        thought.append(bool(reasoning.strip()) or "</think>" in content or "<think>" in content)
except Exception as e:
    print("greedy_check=failed")
    print("greedy_error=" + " ".join(str(e).split())[:200])
else:
    hashes = [hashlib.sha256(o.encode()).hexdigest()[:12] for o in outs]
    print("greedy_check=" + ("identical" if len(set(hashes)) == 1 else "differs"))
    print(f"greedy_variants={len(set(hashes))}\ngreedy_runs={len(hashes)}\ngreedy_hash={hashes[0]}")
    print("greedy_reasoning=" + ("yes" if all(thought) else "no" if not any(thought) else "mixed"))
PY

# ---------------------------------------------------------------- collect
if [ -n "$env_file" ]; then
  cp "$env_file" "$tmp/env"
else
  set -- --endpoint "$endpoint" --model "$model" --server-cmd-out "$tmp/cmd.auto"
  [ -n "$server_cmd_file" ] && set -- "$@" --server-cmd-file "$server_cmd_file"
  sh "$here/collect-env.sh" "$@" > "$tmp/env"
fi

get() { sed -n "s/^$1=//p" "$tmp/env" | head -n1; }
pl=$(get gpu_power_limit_w)
power_src=declared
if [ -z "$power_limit" ]; then
  matches "$pl" '[0-9]+(\.[0-9]+)?' ||
    die "GPU power limit not detected here; pass --power-limit W (or 'stock')"
  power_limit=$pl power_src=detected
fi

# Raw declared values; meta.json keeps these and the collected ones as is.
{
  printf 'submitter=%s\ntp=%s\npp=%s\nquant=%s\nkv=%s\nspec=%s\nthinking=%s\npower_limit=%s\n' \
    "$submitter" "$tp" "$pp" "$quant" "$kv" "$spec" "$thinking" "$power_limit"
  printf 'power_limit_source=%s\n' "$power_src"
  [ -n "$pcie" ] && printf 'pcie=%s\n' "$pcie"
  [ -n "$special" ] && printf 'special_notes=%s\n' "$special"
  [ -n "$mem_bw" ] && printf 'mem_bw=%s\n' "$mem_bw"
  printf 'betterbench=%s\nbetterbench_build=%s\n' "$have_ver" "$bb_build"
  printf 'bench_standard=%s\nrun_mode=%s\nconcurrency=%s\n' "$STANDARD_VERSION" \
    "$([ $quick = 1 ] && echo quick || echo full)" "$([ $no_conc = 1 ] && echo off || echo on)"
} > "$tmp/mandatory"
grep -Ev '^[[:space:]]*(#|$)' "$tmp/env" > "$tmp/collected" || true
if grep -Evq '^[a-z0-9_]+=' "$tmp/collected"; then
  die "malformed line in collected env (want key=value, lowercase keys)"
fi
for k in $(cut -d= -f1 "$tmp/mandatory"); do
  if grep -q "^$k=" "$tmp/collected"; then die "collected env must not set mandatory key '$k'"; fi
done

# Launch command: the user's file wins, else what llama-swap reports.
# Secrets in env vars / flags are redacted either way.
cmd_src=""
if [ -n "$server_cmd_file" ]; then cmd_src="file:$(basename "$server_cmd_file")"; cp "$server_cmd_file" "$tmp/cmd"
elif [ -s "$tmp/cmd.auto" ]; then cmd_src="llama-swap /running"; cp "$tmp/cmd.auto" "$tmp/cmd"; fi
: > "$tmp/cmd.red"
if [ -n "$cmd_src" ]; then
  python3 - "$tmp/cmd" "$tmp/cmd.red" <<'PY'
import re, sys
s = open(sys.argv[1], encoding="utf-8", errors="replace").read()
s = re.sub(r'(?i)\b([A-Z0-9_]*(?:TOKEN|SECRET|PASSWORD|PASSWD|API_?KEY)[A-Z0-9_]*=)\S+', r'\1<redacted>', s)
s = re.sub(r'(?i)(--(?:api-key|hf-token|token)[= ])\S+', r'\1<redacted>', s)
open(sys.argv[2], "w", encoding="utf-8").write(s if s.endswith("\n") else s + "\n")
PY
fi

# The notes are grouped for reading: one chip per topic, nothing twice.
# The context size is left out - BetterBench shows it from --max-model-len.
# launch.json: the settings parsed from the launch command, for meta.json.
python3 "$here/notes.py" "$tmp/mandatory" "$tmp/collected" "$tmp/measured" "$tmp/cmd.red" \
  "$tmp/launch.json" "$here/models.tsv" > "$tmp/notes"

engine=$(get engine) gpu=$(get gpu_model) ctx=$(get ctx)
[ "$engine" != unknown ] || echo "bench.sh: warning: engine not detected; result is hard to compare" >&2
if [ "$power_src" = declared ] && [ "$power_limit" != stock ] && matches "$pl" '[0-9.]+' &&
   [ "$(awk -v a="$pl" -v b="$power_limit" 'BEGIN{print (a-b>1||b-a>1)}')" = 1 ]; then
  echo "bench.sh: warning: --power-limit $power_limit W but the GPU reports $pl W" >&2
fi
# File names: <YYMMDD>_<submitter>_<model>_<engine>_<N>x-<gpu>[_quick][_2],
# with N the GPUs the model runs on (tp x pp); _2, _3, ... for another run of
# the same setup on the same day. Fields are joined with _ since
# model names have dashes. The run folder and the exported results.json/.html
# are named alike, so a file sent on its own still says what it is.
slug() { tr 'A-Z' 'a-z' | sed -e 's/[^a-z0-9.]\{1,\}/-/g' -e 's/^-//' -e 's/-$//'; }
gpu=$(printf '%s' "$gpu" | slug)
name="$(printf '%s' "$model" | slug)_$(printf '%s' "$engine" | slug)_$((tp * pp))x-${gpu:-unknown}"
run_id="$(date +%y%m%d)_$(printf '%s' "$submitter" | slug)_$name"
[ $quick = 1 ] && run_id="${run_id}_quick"
base=$run_id i=1
while [ -e "$results_dir/$run_id" ] || [ -e "$results_dir/$run_id.failed" ]; do
  i=$((i + 1)); run_id="${base}_$i"
done
run_dir="$results_dir/$run_id"
results="$run_dir/$run_id.json"

# ---------------------------------------------------------------- run
set -- run --no-update-check --endpoint "$endpoint" --model "$model" \
       --config "$run_dir/config.json" --name "$name" --out "$results"
[ $quick = 1 ] && set -- "$@" --quick
[ $no_conc = 1 ] && set -- "$@" --no-concurrency
# Through a proxy /v1/models often lacks the context size; hand over what the
# engine itself reported so prefill depths that don't fit are skipped cleanly.
matches "$ctx" '[1-9][0-9]*' && set -- "$@" --max-model-len "$ctx"
while IFS= read -r line; do set -- "$@" --note "$line"; done < "$tmp/notes"

if [ $dry = 1 ]; then
  echo "dry run - would write $run_dir/ and run:"
  printf '  betterbench'
  for a; do case $a in *[[:space:]]*) printf " '%s'" "$a" ;; *) printf ' %s' "$a" ;; esac; done
  echo
  exit 0
fi

mkdir -p "$results_dir"
mkdir "$run_dir" || die "cannot create $run_dir"
cp "$here/config.json" "$run_dir/config.json"
[ -n "$cmd_src" ] && cp "$tmp/cmd.red" "$run_dir/server-cmd.txt"

STANDARD_VERSION=$STANDARD_VERSION CMD_SRC=$cmd_src ENDPOINT=$endpoint MODEL=$model NAME=$name NOTES=$tmp/notes \
MEASURED=$tmp/measured LAUNCH=$tmp/launch.json \
python3 - "$tmp/mandatory" "$tmp/collected" "$run_dir/meta.json" "$@" <<'PY'
import json, os, sys, time
def kv(path):
    with open(path, encoding="utf-8") as f:
        return dict(l.rstrip("\n").split("=", 1) for l in f if "=" in l)
src = os.environ["CMD_SRC"]
meta = {
    "bench_standard": os.environ["STANDARD_VERSION"],
    "created": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
    "endpoint": os.environ["ENDPOINT"],
    "model": os.environ["MODEL"],
    "name": os.environ["NAME"],
    "notes": kv(os.environ["NOTES"]),
    "mandatory": kv(sys.argv[1]),
    "collected": kv(sys.argv[2]),
    "measured": kv(os.environ["MEASURED"]),
    "launch": json.load(open(os.environ["LAUNCH"], encoding="utf-8")),
    "server_cmd_file": "server-cmd.txt" if src else None,
    "server_cmd_source": src or None,
    "betterbench_argv": ["betterbench"] + sys.argv[4:],
}
with open(sys.argv[3], "w", encoding="utf-8") as f:
    json.dump(meta, f, indent=2)
    f.write("\n")
PY

# Power is sampled where the GPU is: only when BetterBench runs on the server.
sampler=""
if [ -z "$env_file" ]; then
  sh "$here/gpu-power.sh" 2 > "$run_dir/power.csv" 2>/dev/null &
  sampler=$!
  trap 'kill "$sampler" 2>/dev/null || true; rm -rf "$tmp"' EXIT INT TERM
fi
echo "running betterbench -> $run_dir" >&2
[ $verbose = 1 ] && sed 's/^/  note: /' "$tmp/notes" >&2
t_start=$(date +%s.%N)
# Full output always goes to betterbench.log; the terminal gets all of it
# (--verbose) or the progress lines and anything that looks like trouble.
# timeline.tsv stamps each progress line, for the energy of each phase.
{ PYTHONUNBUFFERED=1 betterbench "$@" 2>&1 || echo $? > "$tmp/bb_rc"; } |
  tee "$run_dir/betterbench.log" |
  python3 -uc 'import sys, time
tl = open(sys.argv[1], "w", encoding="utf-8")
for line in iter(sys.stdin.readline, ""):
    if line.startswith("["):
        tl.write(f"{time.time():.3f}\t{line}"); tl.flush()
    sys.stdout.write(line); sys.stdout.flush()' "$run_dir/timeline.tsv" |
  if [ $verbose = 1 ]; then cat; else grep --line-buffered -E '^\[|^phases|warn|WARN|rror|Traceback' || true; fi >&2
if [ -s "$tmp/bb_rc" ]; then
  mv "$run_dir" "$run_dir.failed" 2>/dev/null || true
  die "betterbench failed (exit $(cat "$tmp/bb_rc")); output in $run_dir.failed/betterbench.log"
fi
t_end=$(date +%s.%N)
if [ -n "$sampler" ]; then
  kill "$sampler" 2>/dev/null; wait "$sampler" 2>/dev/null || true
  [ -s "$run_dir/power.csv" ] || rm -f "$run_dir/power.csv"
fi

# Energy (whole run and per phase) and decode as % of memory bandwidth, from
# what the run measured. They come after the run, so they go to meta.json
# ("post_run"), not into the notes of the results file.
T0=$t_start T1=$t_end python3 "$here/postrun.py" "$run_dir" "$results" ||
  echo "bench.sh: warning: post-run figures failed" >&2

# BetterBench with GGZ14/BetterBench#4 fingerprints PCIe and BAR itself
# (env.gpu.pci), on the machine BetterBench runs on. Say so when that is not
# the benchmarked GPU, or when it disagrees with collect-env.sh.
ENV_FILE=$env_file python3 - "$results" "$tmp/collected" <<'PY' || true
import json, os, sys
pci = ((json.load(open(sys.argv[1], encoding="utf-8")).get("env") or {}).get("gpu") or {}).get("pci")
if not pci:
    sys.exit()
with open(sys.argv[2], encoding="utf-8") as f:
    c = dict(l.rstrip("\n").split("=", 1) for l in f if "=" in l)
bdf, rebar = c.get("gpu_bdf", "unknown"), c.get("rebar", "unknown")
mine = next((g for g in pci if g.get("pci_address") == bdf), None)
if mine is None:
    where = "expected with --env-file" if os.environ["ENV_FILE"] else "different GPU or machine?"
    print(f"bench.sh: note: BetterBench's own GPU fingerprint (env.gpu.pci) lists "
          f"{', '.join(g.get('pci_address', '?') for g in pci)}, not the benchmarked GPU {bdf} "
          f"({where}); the gpu/pcie notes describe the server", file=sys.stderr)
elif rebar != "unknown" and mine.get("resizable_bar", "").split()[-1:] != [rebar]:
    print(f"bench.sh: warning: ReBAR {rebar} per collect-env.sh, but BetterBench reads "
          f"{mine.get('resizable_bar')} ({mine.get('largest_bar_mib')} MiB BAR)", file=sys.stderr)
PY
echo
echo "done: $run_dir"
ls -1 "$run_dir"
__BENCH_STANDARD_EOF__
cat > "$d/collect-env.sh" <<'__BENCH_STANDARD_EOF__'
#!/bin/sh
# collect-env.sh - run ON THE INFERENCE SERVER. Prints a flat key=value list
# describing the hardware and the inference engine behind an endpoint.
# Never aborts on detection: anything it cannot find is reported as "unknown".
#
# usage: collect-env.sh [--endpoint URL] [--model ID] [--api-key KEY] [--server-cmd-out FILE]
#                       [--server-cmd-file FILE]
#   --endpoint        OpenAI-compatible base, e.g. http://localhost:8080/v1 (omit: hardware only)
#   --model           model id as sent to the endpoint (needed behind llama-swap)
#   --server-cmd-out  behind llama-swap: write the model's launch command (raw) to FILE
#   --server-cmd-file the launch command when not behind llama-swap (finds the container)
# env: BETTERBENCH_API_KEY, PROBE_TIMEOUT (s, default 10), LOAD_TIMEOUT (s, default 600),
#      MEASURE_BW=0 (skip the bandwidth test), BW_PYTHON (python with torch for it),
#      HASH_MODEL=0 (skip hashing the model file)

set -u
LC_ALL=C; export LC_ALL

endpoint="" model="" api_key="${BETTERBENCH_API_KEY:-}" cmd_out="" cmd_file=""
PROBE_TIMEOUT=${PROBE_TIMEOUT:-10}
LOAD_TIMEOUT=${LOAD_TIMEOUT:-600}

need() { [ "$1" -ge 2 ] || { echo "collect-env: $2 needs a value" >&2; exit 2; }; }
while [ $# -gt 0 ]; do
  case "$1" in
    --endpoint)       need $# "$1"; endpoint=$2; shift 2 ;;
    --model)          need $# "$1"; model=$2; shift 2 ;;
    --api-key)        need $# "$1"; api_key=$2; shift 2 ;;
    --server-cmd-out) need $# "$1"; cmd_out=$2; shift 2 ;;
    --server-cmd-file) need $# "$1"; cmd_file=$2; shift 2 ;;
    -h|--help)        sed -n '2,14p' "$0"; exit 0 ;;
    *) echo "collect-env: unknown argument: $1" >&2; exit 2 ;;
  esac
done

tmp=$(mktemp -d) || exit 1
trap 'rm -rf "$tmp"' EXIT INT TERM
# Header via a file so the key never shows up in `ps`.
if [ -n "$api_key" ]; then printf 'Authorization: Bearer %s\n' "$api_key" > "$tmp/hdr"
else printf 'Accept: application/json\n' > "$tmp/hdr"; fi

have() { command -v "$1" >/dev/null 2>&1; }

# jget FILE EXPR - evaluate a python expression over the parsed JSON `j`
# (and `arg` = $JARG); prints nothing on any failure. Tolerates junk before
# the JSON (xpu-smi prints "[Error] ..." lines on stdout).
jget() {
  have python3 || return 0
  python3 - "$1" "$2" <<'PY' 2>/dev/null
import json, os, sys
try:
    raw = open(sys.argv[1], encoding="utf-8", errors="replace").read()
    try:
        j = json.loads(raw)
    except ValueError:
        j = json.loads(raw[raw.index("{"):])
    v = eval(sys.argv[2], {"j": j, "arg": os.environ.get("JARG", "")})
    if v is not None and v != "":
        print(" ".join(str(v).split()))
except Exception:
    pass
PY
}

# fetch URL OUTFILE [TIMEOUT] - succeeds only on HTTP 2xx.
fetch() {
  have curl || return 1
  code=$(curl -s -m "${3:-$PROBE_TIMEOUT}" -o "$2" -w '%{http_code}' -H @"$tmp/hdr" "$1" 2>/dev/null) || code=000
  case "$code" in 2*) return 0 ;; *) return 1 ;; esac
}

# Strip vendor boilerplate so the same card reads the same everywhere.
norm_gpu() {
  sed -e 's/([RT]M*)//g' -e 's/^ *Intel *//' -e 's/^ *NVIDIA *//' -e 's/^ *AMD *//' \
      -e 's/ Graphics *$//' -e 's/  */ /g' -e 's/^ //' -e 's/ $//'
}

kv() { printf '%s=%s\n' "$1" "$(printf '%s' "${2:-unknown}" | tr '\n\r' '  ')"; }

# "16.0 GT/s PCIe" -> 4
pcie_gen() {
  case "$1" in
    2.5*) echo 1 ;; 5.0*|5\ *) echo 2 ;; 8.0*|8\ *) echo 3 ;; 16.0*|16\ *) echo 4 ;;
    32.0*|32\ *) echo 5 ;; 64.0*|64\ *) echo 6 ;; *) echo "" ;;
  esac
}
# pcie_of BDF - sets pcie_link (negotiated now) and pcie_max (what card and slot
# both support) for the link into the slot. Cards with their own PCIe switch
# (Intel Arc, some AMD) expose an internal link on the GPU function itself, so
# walk up through bridges of the GPU's vendor to the switch's upstream port.
pcie_of() {
  d=$(readlink -f "/sys/bus/pci/devices/$1" 2>/dev/null) && [ -f "$d/vendor" ] || return 0
  vendor=$(cat "$d/vendor")
  while p=${d%/*}; [ -f "$p/class" ] && [ "$(cat "$p/vendor")" = "$vendor" ]; do
    case $(cat "$p/class") in 0x0604*) d=$p ;; *) break ;; esac
  done
  p=${d%/*}
  g=$(pcie_gen "$(cat "$d/current_link_speed" 2>/dev/null)") w=$(cat "$d/current_link_width" 2>/dev/null)
  [ -n "$g" ] && [ -n "$w" ] && pcie_link="Gen$g x$w"
  g=$(pcie_gen "$(cat "$d/max_link_speed" 2>/dev/null)") w=$(cat "$d/max_link_width" 2>/dev/null)
  if [ -f "$p/max_link_speed" ]; then
    pg=$(pcie_gen "$(cat "$p/max_link_speed")") pw=$(cat "$p/max_link_width" 2>/dev/null)
    [ -n "$pg" ] && [ "$pg" -lt "${g:-99}" ] && g=$pg
    [ -n "$pw" ] && [ "$pw" -lt "${w:-99}" ] && w=$pw
  fi
  [ -n "$g" ] && [ -n "$w" ] && pcie_max="Gen$g x$w"
  return 0
}

# ---------------------------------------------------------------- GPU
gpu_vendor=none gpu_model="" gpu_count=0 gpu_vram_gb="" gpu_driver="" gpu_power_limit_w="" gpu_bdf=""
if have nvidia-smi && q=$(nvidia-smi --query-gpu=name,memory.total,driver_version,power.limit,pci.bus_id \
                          --format=csv,noheader,nounits 2>/dev/null) && [ -n "$q" ]; then
  gpu_vendor=nvidia
  gpu_count=$(printf '%s\n' "$q" | grep -c .)
  gpu_model=$(printf '%s\n' "$q" | cut -d, -f1 | norm_gpu | sort -u | paste -sd+ -)
  first=$(printf '%s\n' "$q" | head -n1)
  gpu_vram_gb=$(printf '%s' "$first" | cut -d, -f2 | awk '$1+0>0 {printf "%d", $1/1024+0.5}')
  gpu_driver=$(printf '%s' "$first" | cut -d, -f3 | tr -d ' ')
  gpu_power_limit_w=$(printf '%s' "$first" | cut -d, -f4 | awk '$1+0>0 {printf "%g", $1}')
  # 00000000:01:00.0 -> 0000:01:00.0
  gpu_bdf=$(printf '%s' "$first" | cut -d, -f5 | tr -d ' ' | tr 'A-F' 'a-f' | sed 's/^[0-9a-f]*\([0-9a-f]\{4\}:\)/\1/')
elif have rocm-smi && rocm-smi --showproductname --json > "$tmp/rp" 2>/dev/null; then
  gpu_vendor=amd
  rocm-smi --showmeminfo vram --json > "$tmp/rm" 2>/dev/null
  rocm-smi --showdriverversion --json > "$tmp/rd" 2>/dev/null
  rocm-smi --showmaxpower --json > "$tmp/rw" 2>/dev/null
  rocm-smi --showbus --json > "$tmp/rb" 2>/dev/null
  gpu_bdf=$(jget "$tmp/rb" 'next(v["PCI Bus"] for k, v in j.items() if k.startswith("card")).lower()')
  gpu_count=$(jget "$tmp/rp" 'len([k for k in j if k.startswith("card")])')
  gpu_model=$(jget "$tmp/rp" '"+".join(sorted({v.get("Card Series") or v.get("Card series") or v.get("Card model", "") for k, v in j.items() if k.startswith("card")}))' | norm_gpu)
  gpu_vram_gb=$(jget "$tmp/rm" 'round(int(next(v["VRAM Total Memory (B)"] for k, v in j.items() if k.startswith("card"))) / 2**30)')
  gpu_driver=$(jget "$tmp/rd" 'j["system"]["Driver version"]')
  gpu_power_limit_w=$(jget "$tmp/rw" '"%g" % float(next(v for k, v in next(c for n, c in j.items() if n.startswith("card")).items() if "Power" in k))')
elif have xpu-smi && xpu-smi discovery -j > "$tmp/xl" 2>/dev/null; then
  gpu_vendor=intel
  gpu_count=$(jget "$tmp/xl" 'len(j["device_list"])')
  gpu_model=$(jget "$tmp/xl" '"+".join(sorted({d["device_name"] for d in j["device_list"]}))' | norm_gpu)
  dev0=$(jget "$tmp/xl" 'j["device_list"][0]["device_id"]')
  gpu_bdf=$(jget "$tmp/xl" 'j["device_list"][0]["pci_bdf_address"].lower()')
  if [ -n "$dev0" ]; then
    xpu-smi discovery -d "$dev0" -j > "$tmp/xd" 2>/dev/null
    gpu_vram_gb=$(jget "$tmp/xd" 'round(int(j["memory_physical_size_byte"]) / 2**30)')
    gpu_driver=$(jget "$tmp/xd" 'j["driver_version"]')
    # Newer xpu-smi takes named metrics; the old numeric -m syntax is gone.
    gpu_power_limit_w=$(xpu-smi dump --device "$dev0" --metrics power.limit --number 1 2>/dev/null \
                        | awk -F', *' 'NR>1 && $3+0>0 {printf "%g", $3; exit}')
  fi
fi
[ -n "$gpu_count" ] || gpu_count=unknown

# ---------------------------------------------------------------- host
# In a VM the GPU hangs off a virtual root port whose link figures are made
# up, so PCIe is only measured on bare metal.
virt=$(systemd-detect-virt --vm 2>/dev/null) || virt=none
pcie_link="" pcie_max=""
if [ "$virt" = none ] && [ -n "$gpu_bdf" ]; then pcie_of "$gpu_bdf"
elif [ "$virt" != none ]; then pcie_link="unknown (VM)" pcie_max="unknown (VM)"; fi

# Largest BAR of the GPU function: about VRAM-sized with Resizable BAR on,
# 256 MiB or less when off - the rule BetterBench's own fingerprint uses
# (GGZ14/BetterBench#4). Passthrough keeps BAR sizes, so this holds in a VM too.
gpu_bar_mib="" rebar=""
if [ -n "$gpu_bdf" ] && [ -r "/sys/bus/pci/devices/$gpu_bdf/resource" ] && have python3; then
  gpu_bar_mib=$(python3 - "/sys/bus/pci/devices/$gpu_bdf/resource" <<'PY' 2>/dev/null
import sys
bars = []
for line in open(sys.argv[1]):
    try:
        start, end, _ = (int(x, 16) for x in line.split())
    except ValueError:
        continue
    if end > start:
        bars.append((end - start + 1) >> 20)
if bars:
    print(max(bars))
PY
)
  if [ -n "$gpu_bar_mib" ]; then
    if [ "$gpu_bar_mib" -gt 256 ]; then rebar=on; else rebar=off; fi
  fi
fi

cpu_model=$(lscpu 2>/dev/null | sed -n 's/^Model name: *//p' | head -n1)
[ -n "$cpu_model" ] || cpu_model=$(sed -n 's/^model name[[:space:]]*: *//p' /proc/cpuinfo 2>/dev/null | head -n1)
ram_gb=$(awk '/^MemTotal:/ {printf "%d", $2/1048576+0.5}' /proc/meminfo 2>/dev/null)
os=$( (. /etc/os-release 2>/dev/null && printf '%s' "${PRETTY_NAME:-}") )
[ -n "$os" ] || os=$(uname -s 2>/dev/null)
kernel=$(uname -r 2>/dev/null)

# ---------------------------------------------------------------- engine
proxy=none engine=unknown engine_version="" model_file="" ctx="" engine_slots=""
if [ -n "$endpoint" ]; then
  base=${endpoint%/}; base=${base%/v1}
  prefix=$base
  t1=$PROBE_TIMEOUT
  if fetch "$base/running" "$tmp/running" && [ -n "$(jget "$tmp/running" '"running" in j and "y"')" ]; then
    proxy=llama-swap
    if [ -n "$model" ]; then
      prefix="$base/upstream/$model"
      export JARG="$model"
      state=$(jget "$tmp/running" 'next((r.get("state") for r in j["running"] if r.get("model") == arg), "")')
      if [ "$state" != ready ]; then
        echo "collect-env: $model is not loaded; llama-swap loads it on this probe (up to ${LOAD_TIMEOUT}s)" >&2
        t1=$LOAD_TIMEOUT
      fi
    fi
  fi

  if fetch "$prefix/props" "$tmp/props" "$t1" \
     && [ -n "$(jget "$tmp/props" '("build_info" in j or "default_generation_settings" in j) and "y"')" ]; then
    engine=llama.cpp
    engine_version=$(jget "$tmp/props" 'j.get("build_info")')
    model_file=$(jget "$tmp/props" 'j.get("model_path")')
    ctx=$(jget "$tmp/props" '(j.get("default_generation_settings") or {}).get("n_ctx") or j.get("n_ctx")')
    engine_slots=$(jget "$tmp/props" 'j.get("total_slots")')
  elif fetch "$prefix/version" "$tmp/version" "$t1" \
       && v=$(jget "$tmp/version" 'j.get("version")') && [ -n "$v" ]; then
    engine_version=$v
    if fetch "$prefix/v1/models" "$tmp/models"; then
      export JARG="$model"
      # Behind a proxy the served name differs from the routed id, so a single
      # entry is taken as is.
      pick='next((m for m in j["data"] if m.get("id") == arg), j["data"][0] if len(j["data"]) == 1 else {})'
      [ "$(jget "$tmp/models" "($pick).get('owned_by')")" = vllm ] && engine=vllm
      ctx=$(jget "$tmp/models" "($pick).get('max_model_len')")
      model_file=$(jget "$tmp/models" "($pick).get('root')")
    fi
  fi

  # Behind llama-swap the launch command is known: keep it, and map a
  # container path (-v HOST:/model) back to the host path.
  if [ "$proxy" = llama-swap ] && [ -n "$model" ] && fetch "$base/running" "$tmp/running"; then
    export JARG="$model"
    jget "$tmp/running" 'next((r.get("cmd") for r in j["running"] if r.get("model") == arg), "")' > "$tmp/cmd"
    if [ -s "$tmp/cmd" ]; then
      [ -n "$cmd_out" ] && cp "$tmp/cmd" "$cmd_out"
      if [ -n "$model_file" ] && have python3; then
        host=$(python3 - "$tmp/cmd" "$model_file" <<'PY' 2>/dev/null
import re, sys
cmd, path = open(sys.argv[1]).read(), sys.argv[2]
for src, dst in re.findall(r'(?:-v|--volume)[ =](\S+?):(/[^\s:]*)', cmd):
    if path == dst or path.startswith(dst.rstrip("/") + "/"):
        print(src + path[len(dst):]); break
PY
)
        [ -n "$host" ] && model_file=$host
      fi
    fi
  fi
fi

# Weight bytes as stored: a single file, the parts of a split GGUF
# (-00001-of-0000N.gguf), or the *.safetensors of a model directory, without
# an MTP head (*mtp*), which plain decoding doesn't read.
model_bytes=""
if [ -f "$model_file" ]; then
  case $model_file in
    *-00001-of-[0-9]*.gguf) set -- "${model_file%-00001-of-*}"-[0-9]*-of-[0-9]*.gguf ;;
    *) set -- "$model_file" ;;
  esac
  model_bytes=$(stat -c %s "$@" 2>/dev/null | awk '{s += $1} END {if (s) printf "%d", s}')
elif [ -d "$model_file" ]; then
  model_bytes=$(find "$model_file" -maxdepth 1 -name '*.safetensors' ! -name '*mtp*' -exec stat -c %s {} + 2>/dev/null |
                awk '{s += $1} END {if (s) printf "%d", s}')
fi

[ -s "$tmp/cmd" ] || { [ -n "$cmd_file" ] && cp "$cmd_file" "$tmp/cmd" 2>/dev/null; }
# A docker server: the exact image, since tags like llama.cpp's server-intel
# move daily (the llama.cpp build itself is in engine_version).
container="" engine_image=""
[ -s "$tmp/cmd" ] && container=$(tr '\n' ' ' < "$tmp/cmd" |
  sed -n 's/.*docker  *\(run\|create\) .*--name[= ]\([^ ]*\).*/\2/p')
if [ -n "$container" ] && have docker &&
   i=$(docker inspect -f '{{.Config.Image}}@{{.Image}}' "$container" 2>/dev/null); then
  engine_image=$(printf '%s' "$i" | sed 's/@sha256:\(.\{12\}\).*/@\1/')
fi

# vLLM logs what the weights take in GPU memory, per worker. That beats the
# stored size when it quantizes at load (fp8 from bf16 files reads half).
model_loaded_gib=""
if [ "$engine" = vllm ] && [ -n "$container" ] && have docker; then
  model_loaded_gib=$(docker logs "$container" 2>&1 | sed -n 's/.*Model loading took \([0-9.]*\) GiB.*/\1/p' | tail -n1)
fi

# The model's SHA256, checked against the standard models (README, Models).
# The first time takes a while for a big file, then it's cached.
# HASH_MODEL=0 skips it.
model_sha256=""
here=$(cd "$(dirname "$0")" && pwd)
if [ "${HASH_MODEL:-1}" != 0 ] && [ -e "$model_file" ] && have python3; then
  echo "collect-env: hashing the model file (cached after the first time) ..." >&2
  model_sha256=$(python3 "$here/model_hash.py" "$model_file" 2>/dev/null)
fi

# Measured memory bandwidth, the base for "% of peak". mem-bw.py copies random
# data with torch, inside the server's container (same GPU, env and torch), or
# with $BW_PYTHON. Fallback: clpeak, whose test data may compress on Arc and
# read high. A few seconds and 2 GiB of free VRAM; MEASURE_BW=0 skips it.
gpu_mem_bw_gbs="" gpu_mem_bw_tool=""
if [ "${MEASURE_BW:-1}" != 0 ]; then
  if [ -n "${BW_PYTHON:-}" ]; then
    r=$(timeout 300 "$BW_PYTHON" "$here/mem-bw.py" 2>/dev/null)
  elif [ -n "$engine_image" ]; then
    r=$(timeout 300 docker exec -i "$container" python3 - < "$here/mem-bw.py" 2>/dev/null)
  else
    r=""
  fi
  if [ -n "$r" ]; then
    gpu_mem_bw_gbs=${r% *} gpu_mem_bw_tool="torch copy, random, ${r#* } MiB"
  elif have clpeak && [ -n "$gpu_model" ]; then
    echo "collect-env: measuring memory bandwidth with clpeak (MEASURE_BW=0 skips) ..." >&2
    timeout 300 clpeak --global-bandwidth > "$tmp/clpeak" 2>/dev/null
    # Pick the device whose name holds the detected model; take the best width.
    gpu_mem_bw_gbs=$(awk -v want="$gpu_model" '
      /^ *Device:/ { sub(/^ *Device: */, ""); gsub(/\([RT]M*\)/, ""); gsub(/  +/, " "); dev = $0; next }
      /Global memory bandwidth/ { inbw = index(dev, want) > 0; next }
      inbw && /^ *float[0-9]* *:/ { v = $NF + 0; if (v > best) best = v; next }
      inbw && !/^ *float/ { inbw = 0 }
      END { if (best > 0) printf "%.0f", best }' "$tmp/clpeak")
    [ -n "$gpu_mem_bw_gbs" ] && gpu_mem_bw_tool=clpeak
  fi
fi

kv gpu_vendor "$gpu_vendor"
kv gpu_model "$gpu_model"
kv gpu_count "$gpu_count"
kv gpu_vram_gb "$gpu_vram_gb"
kv gpu_driver "$gpu_driver"
kv gpu_power_limit_w "$gpu_power_limit_w"
kv gpu_bdf "$gpu_bdf"
kv pcie_link "$pcie_link"
kv pcie_max "$pcie_max"
kv gpu_bar_mib "$gpu_bar_mib"
kv rebar "$rebar"
kv gpu_mem_bw_gbs "$gpu_mem_bw_gbs"
kv gpu_mem_bw_tool "$gpu_mem_bw_tool"
kv cpu_model "$cpu_model"
kv ram_gb "$ram_gb"
kv os "$os"
kv kernel "$kernel"
kv virt "$virt"
kv proxy "$proxy"
kv engine "$engine"
kv engine_version "$engine_version"
kv engine_slots "$engine_slots"
kv engine_image "$engine_image"
kv model_file "$model_file"
kv model_bytes "$model_bytes"
kv model_loaded_gib "$model_loaded_gib"
kv model_sha256 "$model_sha256"
kv ctx "$ctx"
exit 0
__BENCH_STANDARD_EOF__
cat > "$d/gpu-power.sh" <<'__BENCH_STANDARD_EOF__'
#!/bin/sh
# gpu-power.sh - run ON THE INFERENCE SERVER. Samples the power draw and the
# energy counter and the core clock of all GPUs until killed, one CSV line
# per sample:
#   epoch_s,watts,joules,mhz
# watts is the sum over all GPUs; joules is the sum of the cards' cumulative
# energy counters (empty where the card has none, then integrate the watts);
# mhz is the mean graphics clock over the GPUs.
# Prints nothing at all when no supported tool is found (nvidia-smi, xpu-smi).
#
# usage: gpu-power.sh [INTERVAL_S]   (default 2)

set -u
LC_ALL=C; export LC_ALL
interval=${1:-2}

if command -v nvidia-smi >/dev/null 2>&1 &&
   nvidia-smi --query-gpu=power.draw --format=csv,noheader >/dev/null 2>&1; then
  # total_energy_consumption is in mJ since the driver loaded
  sample() {
    nvidia-smi --query-gpu=power.draw,total_energy_consumption,clocks.gr \
               --format=csv,noheader,nounits 2>/dev/null |
      awk -F', *' '{w += $1; if ($2 + 0 > 0) j += $2 / 1000; else nj = 1; c += $3}
                   END {if (NR) printf "%.2f,%s,%.0f\n", w, nj ? "" : sprintf("%.3f", j), c / NR}'
  }
elif command -v xpu-smi >/dev/null 2>&1; then
  # one call takes about a second
  sample() {
    xpu-smi dump --device -1 --metrics power.draw,energy.consumed,clocks.current.graphics \
                 --number 1 2>/dev/null |
      awk -F', *' 'NR > 1 && $3 + 0 > 0 {w += $3; n++; if ($4 + 0 > 0) j += $4; else nj = 1; c += $5}
                   END {if (n) printf "%.2f,%s,%.0f\n", w, nj ? "" : sprintf("%.3f", j), c / n}'
  }
else
  exit 0
fi

while :; do
  t=$(date +%s.%N)
  s=$(sample)
  [ -n "$s" ] && printf '%s,%s\n' "$t" "$s"
  sleep "$interval"
done
__BENCH_STANDARD_EOF__
cat > "$d/mem-bw.py" <<'__BENCH_STANDARD_EOF__'
"""mem-bw.py - measured GPU memory bandwidth with torch, printed as "GBPS MIB".

Copies a buffer of random floats 20 times and counts read + write. Random
data on purpose: Arc compresses uniform buffers, so a zero-filled test reads
far too high (1227 GB/s with zeros vs 533 GB/s real on a B70). Best of three
rounds. Tries 1 GiB, then smaller buffers when the inference server has taken
most of the VRAM. Prints nothing when there is no usable GPU.

Runs with any python that has torch for the GPU: collect-env.sh runs it inside
the server's own container (docker exec), or with $BW_PYTHON.
"""
import sys
import time

import torch

if hasattr(torch, "xpu") and torch.xpu.is_available():
    dev, sync = "xpu", torch.xpu.synchronize
elif torch.cuda.is_available():          # NVIDIA, and AMD through ROCm
    dev, sync = "cuda", torch.cuda.synchronize
else:
    sys.exit(0)

for mib in (1024, 512, 256):
    try:
        x = torch.rand(mib * 2**20 // 4, device=dev)
        y = torch.empty_like(x)
        break
    except RuntimeError:                 # out of memory
        continue
else:
    sys.exit(0)

y.copy_(x)
sync()
best = 0.0
for _ in range(3):
    t = time.perf_counter()
    for _ in range(20):
        y.copy_(x)
    sync()
    best = max(best, 20 * 2 * x.numel() * 4 / (time.perf_counter() - t) / 1e9)
print(f"{best:.0f} {mib}")
__BENCH_STANDARD_EOF__
cat > "$d/model_hash.py" <<'__BENCH_STANDARD_EOF__'
"""model_hash.py - SHA256 of a model, as the README's Models section defines it.

usage: model_hash.py PATH    (prints the hash, or nothing when PATH can't be read)

A file: its SHA256, like `sha256sum FILE`. A directory: the SHA256 over the
per-file hashes of its *.safetensors, in byte order of the names, exactly like
`sha256sum *.safetensors | LC_ALL=C sort -k2 | sha256sum`.

Hashing a 16 GB file takes a while, so per-file hashes are cached in
~/.cache/bench-standard/sha256.tsv, keyed by path, size and mtime.
"""
import hashlib
import os
import sys

CACHE = os.path.join(os.environ.get("XDG_CACHE_HOME") or os.path.expanduser("~/.cache"),
                     "bench-standard", "sha256.tsv")


def _load_cache():
    cache = {}
    try:
        with open(CACHE, encoding="utf-8") as f:
            for line in f:
                p = line.rstrip("\n").split("\t")
                if len(p) == 4:
                    cache[(p[0], p[1], p[2])] = p[3]
    except OSError:
        pass
    return cache


def _save_cache(cache):
    try:
        os.makedirs(os.path.dirname(CACHE), exist_ok=True)
        tmp = CACHE + f".{os.getpid()}"
        with open(tmp, "w", encoding="utf-8") as f:
            for (path, size, mtime), h in sorted(cache.items()):
                f.write(f"{path}\t{size}\t{mtime}\t{h}\n")
        os.replace(tmp, CACHE)
    except OSError:
        pass


def file_sha256(path, cache):
    st = os.stat(path)
    key = (os.path.realpath(path), str(st.st_size), str(st.st_mtime_ns))
    if key not in cache:
        h = hashlib.sha256()
        with open(path, "rb") as f:
            for block in iter(lambda: f.read(1 << 22), b""):
                h.update(block)
        cache[key] = h.hexdigest()
    return cache[key]


def model_sha256(path, cache=None):
    cache = _load_cache() if cache is None else cache
    if os.path.isdir(path):
        names = sorted((n for n in os.listdir(path) if n.endswith(".safetensors")),
                       key=lambda n: n.encode())
        if not names:
            return None
        listing = "".join(f"{file_sha256(os.path.join(path, n), cache)}  {n}\n" for n in names)
        return hashlib.sha256(listing.encode()).hexdigest()
    return file_sha256(path, cache)


if __name__ == "__main__":
    try:
        cache = _load_cache()
        h = model_sha256(sys.argv[1], cache)
        _save_cache(cache)
    except (OSError, IndexError):
        h = None
    if h:
        print(h)
__BENCH_STANDARD_EOF__
cat > "$d/notes.py" <<'__BENCH_STANDARD_EOF__'
"""notes.py - the notes bench.sh hands BetterBench, one per topic.

usage: notes.py MANDATORY COLLECTED MEASURED CMD LAUNCH_JSON MODELS_TSV > notes
The first three are key=value files (declared, detected by collect-env.sh,
measured by the greedy check), CMD the redacted launch command (may be
empty). Writes the parsed launch settings to LAUNCH_JSON and prints
key=value notes; warnings go to stderr.
"""
import json, shlex, sys
def kv(path):
    with open(path, encoding="utf-8") as f:
        return dict(l.rstrip("\n").split("=", 1) for l in f if "=" in l)
m, c, meas = kv(sys.argv[1]), kv(sys.argv[2]), kv(sys.argv[3])
models = [l.rstrip("\n").split("\t") for l in open(sys.argv[6], encoding="utf-8")
          if l.strip() and not l.startswith("#")]
cmd = open(sys.argv[4], encoding="utf-8").read().strip()
def g(k):
    v = c.get(k, "")
    return "" if v in ("", "unknown") else v
def join(*parts):
    return " · ".join(p for p in parts if p) or "unknown"

vendor = {"intel": "Intel", "nvidia": "NVIDIA", "amd": "AMD"}.get(g("gpu_vendor"), g("gpu_vendor"))
count = g("gpu_count")
gpu = join(" ".join(p for p in (count and count + "x", vendor if vendor != "none" else "",
                                g("gpu_model")) if p),
           g("gpu_vram_gb") and g("gpu_vram_gb") + " GB",
           g("gpu_driver") and "driver " + g("gpu_driver"))

link, top = g("pcie_link"), g("pcie_max")
if m.get("pcie"):
    pcie = m["pcie"] + " (declared)"
elif link and top and link != top:
    pcie = f"{link} now, {top} max"   # idle GPUs drop the link speed
else:
    pcie = link or "unknown"
if g("rebar"):
    pcie += " · ReBAR " + g("rebar")

pl, det = m["power_limit"], g("gpu_power_limit_w")
if pl == "stock":
    power = join("stock", det and det + " W")
else:
    power = pl + " W"
    if det and abs(float(det) - float(pl)) > 1:
        power += f" (GPU reports {det} W)"

virt = g("virt")
host = join(g("cpu_model"), g("ram_gb") and g("ram_gb") + " GB RAM", g("os"),
            g("kernel") and "kernel " + g("kernel"), virt != "none" and virt and "VM " + virt)

# Settings in the launch command that swing results but no API reports:
# batch sizes, flash attention, KV types, env flags. Flags left out of the
# command are the engine's defaults, which change between versions.
try:
    words = shlex.split(cmd.replace("\\\n", " "))
except ValueError:
    words = cmd.split()
env, flags, prog = {}, {}, None
BOOL = {"--no-mmap", "--mlock", "--enforce-eager", "--enable-prefix-caching",
        "--no-enable-prefix-caching", "--enable-chunked-prefill",
        "--no-enable-chunked-prefill", "--cont-batching", "-cb", "--no-cont-batching", "-nocb",
        "-cmoe", "--cpu-moe", "-rm", "--rm", "-d", "--detach", "-it", "-i", "--privileged"}
FA_VALUES = {"on", "off", "auto", "1", "0", "true", "false"}
i = 0
while i < len(words):
    w = words[i]
    nxt = words[i + 1] if i + 1 < len(words) else None
    if prog is None and "=" in w and not w.startswith("-") and w.split("=", 1)[0].isidentifier():
        k, v = w.split("=", 1); env[k] = v                     # FOO=1 cmd
    elif prog is None and not w.startswith("-") and w != "env":
        prog = w
    elif w in ("-e", "--env") and nxt is not None and not nxt.startswith("-"):  # docker -e K=V
        k, _, v = nxt.partition("="); env[k] = v if _ else "(inherited)"; i += 1
    elif w.startswith("--env="):
        k, _, v = w[6:].partition("="); env[k] = v if _ else "(inherited)"
    elif w.startswith("-e") and len(w) > 2 and "=" in w and w[2:].split("=")[0].isidentifier():
        k, v = w[2:].split("=", 1); env[k] = v
    elif w.startswith("-"):
        if "=" in w and w.startswith("--"):
            k, v = w.split("=", 1); flags[k] = v
        elif w in ("-fa", "--flash-attn"):
            if nxt is not None and nxt.lower() in FA_VALUES:
                flags[w] = nxt; i += 1
            else:
                flags[w] = "on"                                   # older bare -fa
        elif w in BOOL or nxt is None or nxt.startswith("-"):
            flags[w] = True
        else:
            flags[w] = nxt; i += 1
    i += 1

def flag(*names):
    for n in names:
        if n in flags:
            return flags[n]
    return None

LLAMA = [("b", ("-b", "--batch-size")), ("ub", ("-ub", "--ubatch-size")),
         ("fa", ("-fa", "--flash-attn")), ("ctk", ("-ctk", "--cache-type-k")),
         ("ctv", ("-ctv", "--cache-type-v")), ("ngl", ("-ngl", "--gpu-layers", "--n-gpu-layers")),
         ("np", ("-np", "--parallel")), ("t", ("-t", "--threads")),
         ("sm", ("-sm", "--split-mode")), ("ts", ("-ts", "--tensor-split")),
         ("ot", ("-ot", "--override-tensor")), ("ncmoe", ("-ncmoe", "--n-cpu-moe")),
         ("cmoe", ("-cmoe", "--cpu-moe")), ("no-mmap", ("--no-mmap",)), ("mlock", ("--mlock",)),
         ("nocb", ("-nocb", "--no-cont-batching"))]
LLAMA_ALWAYS = {"b", "ub", "fa", "ctk", "ctv"}   # shown as "default" when not set
VLLM = ["--max-num-batched-tokens", "--max-num-seqs", "--kv-cache-dtype",
        "--gpu-memory-utilization", "--dtype", "--quantization", "--block-size",
        "--enforce-eager", "--enable-chunked-prefill", "--no-enable-chunked-prefill",
        "--enable-prefix-caching", "--no-enable-prefix-caching", "--attention-backend",
        "--compilation-config", "-O", "--speculative-config"]
launch_kind = g("engine")
if launch_kind not in ("llama.cpp", "vllm"):
    launch_kind = ("llama.cpp" if prog and "llama-server" in prog or flag("-ngl", "-ub", "-ctk")
                   else "vllm" if any(f in flags for f in VLLM) else "")
settings = {}
if launch_kind == "llama.cpp":
    for name, al in LLAMA:
        v = flag(*al)
        if v is not None:
            settings[name] = "on" if v is True else v
        elif name in LLAMA_ALWAYS:
            settings[name] = "default"
elif launch_kind == "vllm":
    for f in VLLM:
        if f in flags:
            settings[f.lstrip("-")] = "on" if flags[f] is True else "".join(str(flags[f]).split())
if not cmd:
    launch = "unknown (pass --server-cmd-file)"
else:
    launch = " · ".join(k if v == "on" and k in ("no-mmap", "mlock", "nocb", "cmoe") or
                        k.startswith(("enable-", "no-enable-", "enforce-")) else f"{k} {v}"
                        for k, v in settings.items()) or "no tuning flags"
# Offline switches and cache paths don't change the numbers.
QUIET = {"HF_HUB_OFFLINE", "TRANSFORMERS_OFFLINE", "HF_DATASETS_OFFLINE", "HF_HOME",
         "VLLM_CACHE_ROOT", "PATH", "HOME", "TZ", "LANG", "LC_ALL"}
env_flags = (" · ".join(f"{k}={v}" for k, v in env.items() if k not in QUIET) or "none"
             ) if cmd else "unknown"
json.dump({"engine": launch_kind or None, "settings": settings, "env": env, "flags": flags},
          open(sys.argv[5], "w", encoding="utf-8"), indent=2, default=str)

# The declared --kv should be what the command sets.
kvset = [x for x in (settings.get("ctk"), settings.get("ctv"), settings.get("kv-cache-dtype"))
         if x and x not in ("default", "auto")]
if kvset and m["kv"] not in kvset + ["/".join(kvset), "_".join(kvset)]:
    print(f"bench.sh: warning: --kv {m['kv']} but the launch command sets "
          f"{'/'.join(kvset)}", file=sys.stderr)

# The model file against the standard models: results only count for those.
mb, sha = g("model_bytes"), g("model_sha256")
std = next((r for r in models if len(r) >= 4 and r[3] == sha), None) if sha else None
if std:
    check = f"standard: {std[0]} {std[2]}"
    if m["quant"] != std[2]:
        print(f"bench.sh: warning: --quant {m['quant']}, but the file is the standard "
              f"{std[0]} {std[2]}; declare --quant {std[2]}", file=sys.stderr)
elif sha:
    check = f"not a standard model (sha256 {sha[:12]})"
    print("bench.sh: warning: the model file is not one of the standard models "
          "(README, Models), so the result won't count", file=sys.stderr)
else:
    check = "hash not checked"
model_file = join(g("model_file"), mb and f"{int(mb) / 1e9:.2f} GB", check)
mem_bw = join(g("gpu_mem_bw_gbs") and
              f'{g("gpu_mem_bw_gbs")} GB/s measured ({g("gpu_mem_bw_tool") or "?"})',
              m.get("mem_bw") and m["mem_bw"] + " GB/s declared")
if meas.get("greedy_check") == "identical":
    greedy = f'identical {meas["greedy_runs"]}/{meas["greedy_runs"]} · {meas["greedy_hash"]}'
elif meas.get("greedy_check") == "differs":
    greedy = f'differs: {meas["greedy_variants"]} variants in {meas["greedy_runs"]} · first {meas["greedy_hash"]}'
else:
    greedy = "failed"

# --thinking is declared, but the greedy replies show whether the model
# reasoned: check one against the other.
seen = meas.get("greedy_reasoning")
thinking = join(m["thinking"], {"yes": "reasoning seen", "no": "no reasoning seen",
                                "mixed": "reasoning in some replies"}.get(seen, ""))
if m["thinking"] == "off" and seen in ("yes", "mixed"):
    print("bench.sh: warning: --thinking off, but the greedy replies contain reasoning;"
          " check the server's chat template or reasoning flags", file=sys.stderr)
elif m["thinking"] in ("on", "low", "medium", "high") and seen == "no":
    print(f"bench.sh: warning: --thinking {m['thinking']}, but the greedy replies contain no"
          " reasoning; thinking may be off on the server", file=sys.stderr)

# The BetterBench build: a release tag says nothing more than the version, a
# commit or local changes do (two installs can share a version number).
build = m.get("betterbench_build", "")
betterbench = "betterbench " + m["betterbench"]
if build and build not in ("v" + m["betterbench"], m["betterbench"]):
    betterbench += " @ " + build

eng = g("engine")
engine = join(" ".join(p for p in (eng, g("engine_version")) if p),
              g("engine_slots") and g("engine_slots") + " slots",
              g("engine_image") and "image " + g("engine_image"),
              g("proxy") not in ("", "none") and "via " + g("proxy"))

notes = [
    ("submitter", m["submitter"]),
    ("gpu", gpu),
    ("pcie", pcie),
    ("power_limit", power),
    ("host", host),
    ("engine", engine),
    ("model_file", model_file),
    ("mem_bw", mem_bw),
    ("parallel", f"tp {m['tp']} · pp {m['pp']}"),
    ("precision", f"weights {m['quant']} · kv {m['kv']}"),
    ("launch", launch),
    ("env_flags", env_flags),
    ("spec", m["spec"]),
    ("thinking", thinking),
    ("greedy_check", greedy),
    ("run", join(m["run_mode"], "concurrency " + m["concurrency"],
                 "bench-standard " + m["bench_standard"], betterbench)),
]
if m.get("special_notes"):
    notes.append(("special_notes", m["special_notes"]))
for k, v in notes:
    print(f"{k}={v}")
__BENCH_STANDARD_EOF__
cat > "$d/postrun.py" <<'__BENCH_STANDARD_EOF__'
"""postrun.py - figures that need the finished run, and the summary.

usage: T0=epoch T1=epoch postrun.py RUN_DIR [RESULTS_JSON]

Reads RESULTS_JSON (default RUN_DIR/results.json), and meta.json, power.csv
(epoch_s,watts,joules,mhz) and timeline.tsv (epoch<TAB>BetterBench progress
line) from RUN_DIR. Writes
energy (whole run and per phase) and the bandwidth figure to meta.json under
"post_run", and prints the summary to stderr.
"""
import bisect
import json
import os
import re
import statistics
import sys


def read_power(path):
    rows = []
    if os.path.exists(path):
        for line in open(path):
            p = line.strip().split(",")
            try:
                rows.append((float(p[0]), float(p[1]), float(p[2]) if p[2] else None,
                             float(p[3]) if len(p) > 3 and p[3] else 0.0))
            except (ValueError, IndexError):
                pass
    return rows


def energy_curve(rows):
    """(times, cumulative joules): from the energy counter when every sample
    has one, else integrated from the power samples."""
    ts = [r[0] for r in rows]
    if all(r[2] is not None for r in rows) and rows[-1][2] >= rows[0][2]:
        return ts, [r[2] - rows[0][2] for r in rows], "energy counter"
    cum = [0.0]
    for a, b in zip(rows, rows[1:]):
        cum.append(cum[-1] + (b[0] - a[0]) * (a[1] + b[1]) / 2)
    return ts, cum, "integrated power"


def joules_between(ts, cum, t0, t1):
    """Energy between two moments, interpolating between samples."""
    def at(t):
        if t <= ts[0]:
            return cum[0]
        if t >= ts[-1]:
            return cum[-1]
        i = bisect.bisect_right(ts, t)
        f = (t - ts[i - 1]) / (ts[i] - ts[i - 1])
        return cum[i - 1] + f * (cum[i] - cum[i - 1])
    return max(0.0, at(t1) - at(t0))


SEGMENT = re.compile(r"^\[(single|prefill|concurrency)\]\s+(.*)$")
WARMUP = re.compile(r"warmup (\d+) \+ (\d+)")


def segments(timeline, t_end):
    """BetterBench prints a progress line when each piece of work starts; a
    piece lasts until the next line. Yields (phase, key, warm-up factor, t0, t1)."""
    marks = []
    for t, line in timeline:
        m = SEGMENT.match(line)
        if not m or "skip" in m.group(2):
            continue
        phase, rest = m.groups()
        key = rest.split(":")[0].strip()
        if phase == "concurrency":
            key = re.sub(r"\D", "", key)
        w = WARMUP.search(rest)
        factor = (int(w.group(1)) + int(w.group(2))) / int(w.group(2)) if w and int(w.group(2)) else 1.0
        marks.append((t, phase, key, factor))
    for i, (t, phase, key, factor) in enumerate(marks):
        yield phase, key, factor, t, marks[i + 1][0] if i + 1 < len(marks) else t_end


def phase_energy(res, rows, timeline, t_end):
    """Joules and joules per token for decode, prefill and each concurrency
    level. Warm-up passes draw power but aren't in the results, so their
    tokens are estimated from the measured passes of the same piece."""
    ts, cum, _ = energy_curve(rows)
    single = res.get("single_stream") or {}
    prefill = {str(p.get("target_depth")): p for p in res.get("prefill") or []}
    conc = {str(x.get("level")): x for x in res.get("concurrency") or []}
    out = {"decode": {"joules": 0.0, "seconds": 0.0, "tokens": 0.0},
           "prefill": {"joules": 0.0, "seconds": 0.0, "tokens": 0.0}, "concurrency": {}}
    for phase, key, factor, t0, t1 in segments(timeline, t_end):
        j = joules_between(ts, cum, t0, t1)
        if phase == "single":
            tok = sum(r.get("completion_tokens") or 0 for r in single.get(key, []) if r.get("ok", True))
            d = out["decode"]
        elif phase == "prefill":
            depth = re.sub(r"\D", "", key)
            tok = sum(prefill.get(depth, {}).get("prompt_tokens") or [])
            d = out["prefill"]
        else:
            x = conc.get(key, {})
            tok, factor = x.get("aggregate_tps", 0) * x.get("wall_s", 0), 1.0
            d = out["concurrency"].setdefault(key, {"joules": 0.0, "seconds": 0.0, "tokens": 0.0})
        d["joules"] += j
        d["seconds"] += t1 - t0
        d["tokens"] += tok * factor
    def finish(d, per=1):
        return {"joules": round(d["joules"]), "avg_w": round(d["joules"] / d["seconds"], 1) if d["seconds"] else None,
                "tokens_incl_warmup_est": round(d["tokens"]),
                "j_per_token" if per == 1 else "j_per_1k_tokens":
                    round(d["joules"] / d["tokens"] * per, 3) if d["tokens"] else None}
    result = {}
    if out["decode"]["seconds"]:
        result["decode"] = finish(out["decode"])
    if out["prefill"]["seconds"]:
        result["prefill"] = finish(out["prefill"], per=1000)
    if out["concurrency"]:
        result["concurrency"] = {k: finish(v) for k, v in out["concurrency"].items()}
    return result


def roofline(single, c, m):
    """Batch-1 decode reads all weights once per token: decode t/s x weight
    bytes is the bandwidth it reaches. The weights are what the engine loaded
    (vLLM logs it per worker) or else what is stored; tensor parallelism
    spreads them over tp GPUs, each with its own bandwidth."""
    def num(v):
        try:
            return float(v)
        except (TypeError, ValueError):
            return None
    tps = [r["decode_tps"] for r in single if r.get("decode_tps")]
    bw = num(c.get("gpu_mem_bw_gbs")) or num(m.get("mem_bw"))
    tp = int(m.get("tp") or 1)
    loaded, stored = num(c.get("model_loaded_gib")), num(c.get("model_bytes"))
    if loaded:
        nbytes, src = loaded * 2**30 * tp, "loaded (engine log)"
    elif stored:
        nbytes, src = stored, "stored files"
    else:
        return None
    if not tps or not bw:
        return None
    med = statistics.median(tps)
    eff = med * nbytes / 1e9
    return {"decode_tps_median": round(med, 2), "weight_bytes": int(nbytes), "weight_source": src,
            "mem_bw_gbs": bw * tp, "gpus": tp, "effective_gbs": round(eff, 1),
            "pct_of_mem_bw": round(100 * eff / (bw * tp), 1)}


def main(d, results=None):
    res = json.load(open(results or f"{d}/results.json", encoding="utf-8"))
    meta = json.load(open(f"{d}/meta.json", encoding="utf-8"))
    c, m = meta["collected"], meta["mandatory"]
    t0, t1 = float(os.environ["T0"]), float(os.environ["T1"])
    post = {"wall_s": round(t1 - t0, 1)}

    single = [r for recs in (res.get("single_stream") or {}).values() for r in recs
              if r.get("ok", True)]
    tok = sum(r.get("completion_tokens") or 0 for r in single)
    tok += sum(round(x.get("aggregate_tps", 0) * x.get("wall_s", 0))
               for x in res.get("concurrency") or [])

    rows = read_power(f"{d}/power.csv")
    timeline = []
    if os.path.exists(f"{d}/timeline.tsv"):
        for line in open(f"{d}/timeline.tsv", encoding="utf-8"):
            t, _, text = line.rstrip("\n").partition("\t")
            try:
                timeline.append((float(t), text))
            except ValueError:
                pass
    if len(rows) >= 2:
        ts, cum, src = energy_curve(rows)
        span = ts[-1] - ts[0]
        joules = cum[-1]
        e = {"joules": round(joules), "source": src, "sampled_s": round(span, 1),
             "avg_w": round(joules / span, 1) if span else None,
             "peak_w": max(r[1] for r in rows), "output_tokens": tok,
             "j_per_output_token": round(joules / tok, 3) if tok else None}
        # A clock-gated idle GPU reads 0 MHz; average the samples where it runs.
        clk = [r[3] for r in rows if r[3] > 0]
        if clk:
            e.update(avg_mhz=round(statistics.mean(clk)), min_mhz=round(min(clk)),
                     max_mhz=round(max(clk)), clock_samples=f"{len(clk)}/{len(rows)}")
        if timeline:
            e["phases"] = phase_energy(res, rows, timeline, t1)
        post["energy"] = e

    r = roofline(single, c, m)
    if r:
        post["roofline"] = r

    # The summary: headline numbers plus the setup that makes them comparable.
    def med(xs):
        xs = [x for x in xs if x]
        return statistics.median(xs) if xs else None
    def f(x, unit, dec=0):
        return "—" if x is None else f"{x:,.{dec}f} {unit}"
    notes = meta["notes"]
    tps = [x["decode_tps"] for x in single if x.get("decode_tps")]
    L = [f"  {meta['model']} · {notes.get('engine', '?')}",
         f"  {notes.get('gpu', '?')} · {notes.get('power_limit', '?')} limit",
         f"  {notes.get('run', '?')} · greedy {notes.get('greedy_check', '?')}",
         f"  decode (batch 1)  {f(med(tps), 't/s', 1)}    TTFT p50  "
         f"{f(med(x.get('ttft_ms') for x in single), 'ms')}"]
    conc = res.get("concurrency") or []
    if conc:
        L.append("  concurrency       " + "   ".join(
            f"{x['level']}: {x.get('aggregate_tps', 0):,.0f} t/s" for x in conc))
    live = [p for p in res.get("prefill") or [] if not p.get("skipped")]
    if live:
        L.append("  prefill           " + "   ".join(
            f"{p['target_depth'] // 1000}k: {f(med(p.get('pp_tps') or []), 't/s')}" for p in live))
    if r:
        L.append(f"  bandwidth         {r['effective_gbs']:.0f} GB/s effective = "
                 f"{r['pct_of_mem_bw']:.0f}% of {r['mem_bw_gbs']:.0f} GB/s "
                 f"(weights {r['weight_bytes'] / 1e9:.2f} GB, {r['weight_source']})")
    if "energy" in post:
        e = post["energy"]
        clock = (f" · clock avg {e['avg_mhz']} MHz ({e['min_mhz']}-{e['max_mhz']})"
                 if "avg_mhz" in e else "")
        L.append(f"  power             avg {e['avg_w']} W, peak {e['peak_w']:.0f} W{clock}")
        ph = e.get("phases") or {}
        parts = []
        if ph.get("decode", {}).get("j_per_token") is not None:
            parts.append(f"decode {ph['decode']['j_per_token']} J/tok at {ph['decode']['avg_w']} W")
        if ph.get("prefill", {}).get("j_per_1k_tokens") is not None:
            parts.append(f"prefill {ph['prefill']['j_per_1k_tokens']} J/1k tok")
        if parts:
            L.append("  energy            " + " · ".join(parts))
        if ph.get("concurrency"):
            L.append("  energy by conc.   " + "   ".join(
                f"{k}: {v['j_per_token']} J/tok" for k, v in ph["concurrency"].items()
                if v.get("j_per_token") is not None))
        L.append(f"  energy (total)    {e['joules'] / 1000:.1f} kJ, "
                 f"{e['j_per_output_token']} J per output token over the whole run")
    print("\n" + "\n".join(L), file=sys.stderr)

    meta["post_run"] = post
    with open(f"{d}/meta.json", "w", encoding="utf-8") as fh:
        json.dump(meta, fh, indent=2)
        fh.write("\n")


if __name__ == "__main__":
    main(*sys.argv[1:3])
